-- resume library and imports (WP-17; PRD resume-suite 6, 12; 02-database 7.1.4, 7.1.5, 7.1.7, 7.1.8, 7.7 as amended).
-- Generated by drizzle-kit for the tables, columns, checks, foreign keys and indexes. Hand edits, all below the
-- generated part unless noted:
--   1. the three facts indexes drizzle-kit put here moved to 0010 (CONCURRENTLY, no transaction; facts is large);
--   2. same-owner triggers (assert_same_owner of 0007) on every new cross-tenant reference;
--   3. employments_guard (the facts_guard rules for employments) and resumes_guard (owns resumes.version);
--   4. snapshot_resume(), the only writer of resume_revisions (SECURITY DEFINER; grants in ops/provision-roles.sql);
--   5. backfill: every existing resume becomes the default base resume of its user's default resume profile (one
--      created when the user has none). Resume sources move to resume_imports in the worker's backfill-sources task,
--      which needs DATA_KEKS and so cannot run here.
-- Deploy note: dropping resumes_user_uq breaks the old api's PUT /api/resume upsert until the new api is live (a
-- failed autosave the web retries); the new code never upserts on it.
CREATE TABLE "employments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"resume_profile_id" uuid,
	"import_id" uuid,
	"title" text NOT NULL,
	"company" text NOT NULL,
	"location" text,
	"dates_text" text,
	"start_month" text,
	"end_month" text,
	"is_current" boolean DEFAULT false NOT NULL,
	"asserted_by" text DEFAULT 'import' NOT NULL,
	"confirmed" boolean DEFAULT false NOT NULL,
	"confirmed_at" timestamp with time zone,
	"import_key" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "employments_title_ck" CHECK (char_length(btrim(title)) BETWEEN 1 AND 200),
	CONSTRAINT "employments_company_ck" CHECK (char_length(btrim(company)) BETWEEN 1 AND 200),
	CONSTRAINT "employments_location_ck" CHECK (char_length(location) <= 120),
	CONSTRAINT "employments_dates_text_ck" CHECK (char_length(dates_text) <= 60),
	CONSTRAINT "employments_start_month_ck" CHECK (start_month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
	CONSTRAINT "employments_end_month_ck" CHECK (end_month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
	CONSTRAINT "employments_dates_ck" CHECK (start_month IS NULL OR end_month IS NULL OR start_month <= end_month),
	CONSTRAINT "employments_current_ck" CHECK (NOT is_current OR end_month IS NULL),
	CONSTRAINT "employments_asserted_by_ck" CHECK (asserted_by IN ('user','import','model')),
	CONSTRAINT "employments_confirmed_at_ck" CHECK (confirmed = (confirmed_at IS NOT NULL)),
	CONSTRAINT "employments_import_key_ck" CHECK (import_key ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
CREATE TABLE "resume_imports" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"resume_profile_id" uuid NOT NULL,
	"source_kind" text NOT NULL,
	"file_name" text,
	"file_key" text,
	"source_text_enc" "bytea" NOT NULL,
	"source_hash" text NOT NULL,
	"parse_status" text DEFAULT 'pending' NOT NULL,
	"parse_attempts" smallint DEFAULT 0 NOT NULL,
	"parse_error" text,
	"parser_version" smallint,
	"parsed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "resume_imports_kind_ck" CHECK (source_kind IN ('pdf','docx','linkedin_pdf','text')),
	CONSTRAINT "resume_imports_file_name_ck" CHECK (char_length(file_name) BETWEEN 1 AND 120),
	CONSTRAINT "resume_imports_file_key_ck" CHECK (starts_with(file_key, 'uploads/' || user_id || '/')),
	CONSTRAINT "resume_imports_enc_ck" CHECK (octet_length(source_text_enc) BETWEEN 30 AND 262144),
	CONSTRAINT "resume_imports_hash_ck" CHECK (source_hash ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "resume_imports_status_ck" CHECK (parse_status IN ('pending','parsing','parsed','failed')),
	CONSTRAINT "resume_imports_error_ck" CHECK (parse_error ~ '^[a-z0-9_]{1,40}$'),
	CONSTRAINT "resume_imports_attempts_ck" CHECK (parse_attempts BETWEEN 0 AND 10),
	CONSTRAINT "resume_imports_shape_ck" CHECK ((parse_status <> 'failed' OR parse_error IS NOT NULL) AND (parse_status <> 'parsed' OR parsed_at IS NOT NULL))
);
