-- employments_guard: the facts_guard rules (0006). Only a user action confirms, unconfirms or edits a role, or creates a
-- confirmed or user-asserted one; a user's edit makes it theirs. confirmed_at and updated_at are the trigger's.
CREATE FUNCTION employments_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  actor  text    := kairos_actor();
  human  boolean := kairos_actor() IN ('user', 'ops');
  edited boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT human AND (NEW.asserted_by = 'user' OR NEW.confirmed) THEN
      RAISE EXCEPTION 'only a user action can create a confirmed or user-asserted employment' USING ERRCODE = '23514', CONSTRAINT = 'employments_actor_required';
    END IF;
    NEW.confirmed_at := CASE WHEN NEW.confirmed THEN now() ELSE NULL END;
  ELSE
    IF NEW.user_id <> OLD.user_id THEN
      RAISE EXCEPTION 'employments.user_id is immutable' USING ERRCODE = '23514', CONSTRAINT = 'employments_user_immutable';
    END IF;
    edited := (NEW.title, NEW.company, NEW.location, NEW.dates_text, NEW.start_month, NEW.end_month, NEW.is_current)
      IS DISTINCT FROM (OLD.title, OLD.company, OLD.location, OLD.dates_text, OLD.start_month, OLD.end_month, OLD.is_current);
    IF (edited OR NEW.confirmed IS DISTINCT FROM OLD.confirmed) AND NOT human THEN
      RAISE EXCEPTION 'only a user action can confirm or edit an employment' USING ERRCODE = '23514', CONSTRAINT = 'employments_actor_required';
    END IF;
    IF NEW.asserted_by IS DISTINCT FROM OLD.asserted_by AND actor <> 'ops' THEN
      RAISE EXCEPTION 'asserted_by changes only through an edit by the owner' USING ERRCODE = '23514', CONSTRAINT = 'employments_actor_required';
    END IF;
    IF edited AND actor = 'user' THEN NEW.asserted_by := 'user'; END IF;
    NEW.confirmed_at := CASE WHEN NOT NEW.confirmed THEN NULL WHEN OLD.confirmed AND NOT edited THEN OLD.confirmed_at ELSE now() END;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER employments_guard_biu BEFORE INSERT OR UPDATE ON employments
  FOR EACH ROW EXECUTE FUNCTION employments_guard();--> statement-breakpoint

-- resumes_guard: version counts document changes (a tailored copy compares its base_version with it, PRD 6.3).
CREATE FUNCTION resumes_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.version := CASE WHEN NEW.document IS DISTINCT FROM OLD.document THEN OLD.version + 1 ELSE OLD.version END;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER resumes_guard_bu BEFORE UPDATE ON resumes
  FOR EACH ROW EXECUTE FUNCTION resumes_guard();--> statement-breakpoint

-- snapshot_resume (database-44, PRD 6.1): the resume's current document as a revision, written BEFORE the change it
-- protects. An 'edit' is skipped when the newest revision is under 10 minutes old or holds the same document, so an
-- autosave burst keeps the state from before its first save. Then the unnamed revisions past the 50 newest go; a named
-- one (user-named, before_ai, before_tailor) is never pruned. Returns the new (or the coalesced) revision id, or null
-- when the resume does not exist. The only writer of resume_revisions: runtime roles get EXECUTE and no INSERT.
CREATE FUNCTION snapshot_resume(p_resume uuid, p_reason text, p_name text, p_created_by text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  doc      jsonb;
  last_id  uuid;
  last_doc jsonb;
  last_at  timestamptz;
  rid      uuid;
BEGIN
  SELECT document INTO doc FROM resumes WHERE id = p_resume FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT id, document, created_at INTO last_id, last_doc, last_at
    FROM resume_revisions WHERE resume_id = p_resume ORDER BY created_at DESC, id DESC LIMIT 1;
  IF p_reason = 'edit' AND last_id IS NOT NULL AND (last_at > now() - interval '10 minutes' OR last_doc = doc) THEN
    RETURN last_id;
  END IF;
  INSERT INTO resume_revisions (resume_id, document, reason, name, created_by)
    VALUES (p_resume, doc, p_reason, p_name, p_created_by) RETURNING id INTO rid;
  DELETE FROM resume_revisions
   WHERE resume_id = p_resume AND name IS NULL
     AND id NOT IN (SELECT id FROM resume_revisions WHERE resume_id = p_resume AND name IS NULL
                     ORDER BY created_at DESC, id DESC LIMIT 50);
  RETURN rid;
END $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION snapshot_resume(uuid, text, text, text) FROM PUBLIC;--> statement-breakpoint

-- Backfill (database-113): a user with a resume and no resume profile gets one, as the default; every existing resume
-- (at most one per user: resumes_user_uq held until this file) joins the user's default profile as its default base.
INSERT INTO resume_profiles (user_id, name, is_default, source_text)
SELECT DISTINCT r.user_id, 'Main', true, ''
  FROM resumes r
 WHERE NOT EXISTS (SELECT 1 FROM resume_profiles p WHERE p.user_id = r.user_id);--> statement-breakpoint
UPDATE resumes r
   SET resume_profile_id = (SELECT p.id FROM resume_profiles p WHERE p.user_id = r.user_id
                             ORDER BY p.is_default DESC, p.created_at, p.id LIMIT 1)
 WHERE r.resume_profile_id IS NULL;--> statement-breakpoint
UPDATE resumes SET is_default = true WHERE kind = 'base' AND archived_at IS NULL;
